INSERT INTO _migration_438_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_biodiversity_s1_001', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In the Linnaean hierarchy, which taxonomic rank comes immediately below kingdom?', 'multiple_choice', NULL, '["A. Class","B. Phylum","C. Order","D. Domain"]', 'B', 'The hierarchy runs domain, kingdom, phylum, class, order, family, genus, species, so the rank directly below kingdom is phylum. A domain is a higher rank introduced in the three-domain classification system. Therefore the correct answer is B: Phylum.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_biodiversity_s1_002', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In the binomial system, the scientific name of a species such as Panthera leo consists of...', 'multiple_choice', NULL, '["A. the family name followed by the genus name","B. the species name followed by the phylum name","C. the genus name followed by the species name","D. two species names joined together"]', 'C', 'Binomial nomenclature gives every species a two-part Latinised name: the genus name (with a capital letter) followed by the species name (lower case), both written in italics, for example Panthera leo for the lion. Therefore the correct answer is C: the genus name followed by the species name.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_biodiversity_s1_003', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which statement about the three-domain classification system is correct?', 'multiple_choice', NULL, '["A. Archaea are eukaryotes because they can live in extreme environments","B. Bacteria have membrane-bound nuclei","C. The three domains are plants, animals and fungi","D. Archaea are prokaryotes that are genetically and biochemically distinct from bacteria"]', 'D', 'The three domains are Bacteria, Archaea and Eukarya. Archaea are prokaryotes like bacteria, but they differ in ribosomal RNA sequences, membrane lipids and cell wall chemistry, which justifies placing them in a separate domain. Therefore the correct answer is D: Archaea are prokaryotes that are genetically and biochemically distinct from bacteria.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_biodiversity_s1_004', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'What does in situ conservation involve?', 'multiple_choice', NULL, '["A. Protecting species within their natural habitats, for example in national parks or reserves","B. Breeding endangered species in zoos","C. Storing seeds in seed banks","D. Maintaining plant collections in botanic gardens"]', 'A', 'In situ conservation maintains species in the wild, for example in protected areas such as national parks and nature reserves, so populations continue to live and evolve within their ecosystems. Zoo breeding programmes, seed banks and botanic gardens are ex situ methods carried out away from the natural habitat. Therefore the correct answer is A: Protecting species within their natural habitats, for example in national parks or reserves.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_biodiversity_s1_005', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Why is a population bottleneck expected to reduce the genetic diversity of a population?', 'multiple_choice', NULL, '["A. Mutation rates always increase after a bottleneck","B. Only a small, often non-representative sample of the original alleles survives in the few remaining individuals","C. Bottlenecks increase gene flow between populations","D. Larger populations always have lower genetic diversity"]', 'B', 'When a population crashes in size, much of its genetic variation is lost because the few survivors carry only a subset of the original alleles. Genetic drift then acts strongly on the small population, and inbreeding among related survivors can reduce heterozygosity still further. Therefore the correct answer is B: Only a small, often non-representative sample of the original alleles survives in the few remaining individuals.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_cambridge'),
('q_albio_biodiversity_s1_006', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A student sampled a grassland plot and counted three plant species: species P = 20 individuals, species Q = 15 individuals and species R = 5 individuals. Calculate Simpson''s Index of Diversity, D = 1 − Σ(n/N)², for this community, giving your answer to two decimal places.', 'calculation', NULL, NULL, '0.59', 'N = 20 + 15 + 5 = 40. For each species n/N is 0.5, 0.375 and 0.125, so Σ(n/N)² = 0.25 + 0.140625 + 0.015625 = 0.40625. Therefore D = 1 − 0.40625 = 0.59375, which rounds to 0.59, a moderate diversity value on the 0 to 1 scale.', 'medium', '5', '3', '240', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_biodiversity_s1_007', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In a mark–release–recapture study of woodlice, 60 animals were caught, marked and released. Two days later, 50 animals were caught, of which 12 were marked. Use the Lincoln index, N = (m × n) / r, to estimate the population size.', 'calculation', NULL, NULL, '250', 'm = 60 animals marked at first capture, n = 50 animals caught in the second sample and r = 12 marked recaptures. N = (60 × 50) / 12 = 3000 / 12 = 250. The estimate assumes the marks persist, marked animals mix randomly back into the population, and there is no significant immigration, emigration, birth or death between the samples.', 'hard', '5', '3', '240', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_cambridge'),
('q_albio_biodiversity_s1_008', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A student is asked about the classification and conservation of organisms.', 'structured', NULL, NULL, '(a) Any two of: no true nucleus (circular DNA lies free in the cytoplasm); no membrane-bound organelles such as mitochondria; smaller 70S ribosomes; a cell wall made of peptidoglycan (murein). (b) Viruses are acellular particles of nucleic acid inside a protein coat and cannot carry out metabolism or reproduce independently — they must hijack a host cell — so they are not regarded as living organisms and fall outside the classification of cellular life. (c) Any one developed point, for example: the species remains in its natural ecosystem, so it continues to interact and co-evolve with other species, and the whole community and habitat are protected at once rather than a single species in isolation.', '(a) Any two of: no true nucleus (circular DNA lies free in the cytoplasm); no membrane-bound organelles such as mitochondria; smaller 70S ribosomes; a cell wall made of peptidoglycan (murein). (b) Viruses are acellular particles of nucleic acid inside a protein coat and cannot carry out metabolism or reproduce independently — they must hijack a host cell — so they are not regarded as living organisms and fall outside the classification of cellular life. (c) Any one developed point, for example: the species remains in its natural ecosystem, so it continues to interact and co-evolve with other species, and the whole community and habitat are protected at once rather than a single species in isolation.', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_438_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_albio_biodiversity_s1_008_a', 'q_albio_biodiversity_s1_008', 'a', 'State two features of their cells that place an organism in the kingdom Prokaryotae.', '2', 'Any two of: no true nucleus (circular DNA lies free in the cytoplasm); no membrane-bound organelles such as mitochondria; smaller 70S ribosomes; a cell wall made of peptidoglycan (murein).', '1'),
('sqp_q_albio_biodiversity_s1_008_b', 'q_albio_biodiversity_s1_008', 'b', 'Explain why viruses are not classified in any kingdom.', '2', 'Viruses are acellular particles of nucleic acid inside a protein coat and cannot carry out metabolism or reproduce independently — they must hijack a host cell — so they are not regarded as living organisms and fall outside the classification of cellular life.', '2'),
('sqp_q_albio_biodiversity_s1_008_c', 'q_albio_biodiversity_s1_008', 'c', 'Describe one advantage of in situ conservation compared with ex situ conservation.', '2', 'Any one developed point, for example: the species remains in its natural ecosystem, so it continues to interact and co-evolve with other species, and the whole community and habitat are protected at once rather than a single species in isolation.', '3');
INSERT INTO _migration_438_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_438_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_438_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_438_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_438_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_438_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint1-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_438_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_438_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_438_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_438_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_438_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_438_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
